@push('script')
    <script>
        (function($) {
            'use strict';

            if (!window.appConfig) {
                return;
            }

            const {
                runningRide,
                notifier: {
                    error
                },
                modalAction: {
                    showNotifyModal
                },
                loader: {
                    buttonLoader
                }
            } = window.appConfig;


            $('.pickup-form').on('submit', function(e) {
                e.preventDefault();
                const $this = $(this);
                const formData = new FormData($this[0]);
                const $submitBtn = $this.find('button[type="submit"]');
                const oldHtml = $submitBtn.html();

                console.log($this.attr('action'));

                $.ajax({
                    type: "POST",
                    url: $this.attr('action'),
                    data: formData,
                    dataType: "json",
                    cache: false,
                    contentType: false,
                    processData: false,
                    beforeSend: () => {
                        $submitBtn.addClass('disabled').attr("disabled", true).html(`
                            <div class="button-loader d-flex gap-2 flex-wrap align-items-center justify-content-center">
                                <div class="spinner-border"></div><span>Loading...</span>
                            </div>
                        `);
                    },
                    complete: () => {
                        $submitBtn.removeClass('disabled').attr("disabled", false).html(oldHtml);
                    },
                    success: function(response) {
                        if (response.status == "success") {
                            notify('success', response?.message);
                            setTimeout(() => {
                                window.location.href = response?.data?.redirect_url;
                            }, 2000);
                        } else {
                            showNotifyModal('error', response?.message || "@lang('Something went wrong, please try again later')");
                        }
                    },
                    error: function(xhr) {
                        const messgae = xhr?.responseJSON?.message ?? "@lang('Something went wrong, please try again later')";
                        showNotifyModal('error', messgae);
                    }
                });

            });


            $(window).on('pageshow', (e) => {
                if (e.originalEvent?.persisted) {
                    const $button = $('.pickup-form').find('button[type="submit"]');
                    buttonLoader($button, false);
                }
            });

            $(window).on('load', () => {
                const $button = $('.pickup-form').find('button[type="submit"]');
                buttonLoader($button, false);
            });


        })(jQuery);
    </script>
@endpush
